#!/usr/bin/env bash
# PreToolUse(Edit|Write): block any edit of flake.nix (generated by flake-file).

event=$(cat)
file_path=$(echo "$event" | jq -r '.tool_input.file_path // empty')

case "$file_path" in
  */flake.nix|flake.nix)
    echo "flake.nix est auto-généré par flake-file. Pour le régénérer : nix run \$NH_OS_FLAKE#write-flake" >&2
    exit 2
    ;;
esac

exit 0
